import{_ as s,a0 as l,w as p,s as i,ao as d,I as o,x as t,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 Centos/RHEL 6.X 上安裝 Wetty | LCTT x X-CMD","titleTemplate":false,"description":"在 Centos/RHEL 6.X 上安裝 Wetty | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Centos/RHEL 6.X 上安裝 Wetty | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Centos/RHEL 6.X 上安裝 Wetty | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151208 Install Wetty on Centos or RHEL 6.X","title":"在 Centos/RHEL 6.X 上安裝 Wetty","tag":"201512","desc":""},"relativePath":"201512/20151208 Install Wetty on Centos or RHEL 6.X.md","filePath":"[post].md"}'),h={name:"201512/20151208 Install Wetty on Centos or RHEL 6.X.md"};function y(m,e,u,w,b,x){const a=l("Link");return p(),i("div",null,[e[13]||(e[13]=d(`<h1 id="在-centos-rhel-6-x-上安裝-wetty" tabindex="-1">在 Centos/RHEL 6.X 上安裝 Wetty <a class="header-anchor" href="#在-centos-rhel-6-x-上安裝-wetty" aria-label="Permalink to “在 Centos/RHEL 6.X 上安裝 Wetty”">​</a></h1><p><img src="http://www.unixmen.com/wp-content/uploads/2015/11/Terminal.png" alt=""></p><p><strong>Wetty 是什麼?</strong></p><p>Wetty = Web + tty</p><p>作為系統管理員，如果你是在 Linux 桌面下，你可以用它像一個 GNOME 終端（或類似的）一樣來連接遠程服務器；如果你是在 Windows 下，你可以用它像使用 Putty 這樣的 SSH 客户端一樣來連接遠程，然後同時可以在瀏覽器中上網並查收郵件等其它事情。</p><p>（LCTT 譯註：簡而言之，這是一個基於 Web 瀏覽器的遠程終端）</p><p><img src="https://github.com/krishnasrinivas/wetty/raw/master/terminal.png" alt=""></p><h3 id="第1步-安裝-epel-源" tabindex="-1">第1步: 安裝 epel 源 <a class="header-anchor" href="#第1步-安裝-epel-源" aria-label="Permalink to “第1步: 安裝 epel 源”">​</a></h3><pre><code># wget http://download.fedoraproject.org/pub/epel/6/i386/epel-release-6-8.noarch.rpm
# rpm -ivh epel-release-6-8.noarch.rpm
</code></pre><h3 id="第2步-安裝依賴" tabindex="-1">第2步：安裝依賴 <a class="header-anchor" href="#第2步-安裝依賴" aria-label="Permalink to “第2步：安裝依賴”">​</a></h3><pre><code># yum install epel-release git nodejs npm -y
</code></pre><p>（LCTT 譯註：對，沒錯，是用 node.js 編寫的）</p><h3 id="第3步-在安裝完依賴後-克隆-github-倉庫" tabindex="-1">第3步：在安裝完依賴後，克隆 GitHub 倉庫 <a class="header-anchor" href="#第3步-在安裝完依賴後-克隆-github-倉庫" aria-label="Permalink to “第3步：在安裝完依賴後，克隆 GitHub 倉庫”">​</a></h3><pre><code># git clone https://github.com/krishnasrinivas/wetty
</code></pre><h3 id="第4步-運行-wetty" tabindex="-1">第4步：運行 Wetty <a class="header-anchor" href="#第4步-運行-wetty" aria-label="Permalink to “第4步：運行 Wetty”">​</a></h3><pre><code># cd wetty
# npm install
</code></pre><h3 id="第5步-從-web-瀏覽器啓動-wetty-並訪問-linux-終端" tabindex="-1">第5步：從 Web 瀏覽器啓動 Wetty 並訪問 Linux 終端 <a class="header-anchor" href="#第5步-從-web-瀏覽器啓動-wetty-並訪問-linux-終端" aria-label="Permalink to “第5步：從 Web 瀏覽器啓動 Wetty 並訪問 Linux 終端”">​</a></h3><pre><code># node app.js -p 8080
</code></pre><h3 id="第6步-為-wetty-安裝-https-證書" tabindex="-1">第6步：為 Wetty 安裝 HTTPS 證書 <a class="header-anchor" href="#第6步-為-wetty-安裝-https-證書" aria-label="Permalink to “第6步：為 Wetty 安裝 HTTPS 證書”">​</a></h3><pre><code># openssl req -x509 -newkey rsa:2048 -keyout key.pem -out cert.pem -days 365 -nodes 
</code></pre><p>(等待完成)</p><h3 id="第7步-通過-https-來使用-wetty" tabindex="-1">第7步：通過 HTTPS 來使用 Wetty <a class="header-anchor" href="#第7步-通過-https-來使用-wetty" aria-label="Permalink to “第7步：通過 HTTPS 來使用 Wetty”">​</a></h3><pre><code># nohup node app.js --sslkey key.pem --sslcert cert.pem -p 8080 &amp;
</code></pre><h3 id="第8步-為-wetty-添加一個用户" tabindex="-1">第8步：為 wetty 添加一個用户 <a class="header-anchor" href="#第8步-為-wetty-添加一個用户" aria-label="Permalink to “第8步：為 wetty 添加一個用户”">​</a></h3><pre><code># useradd &lt;username&gt;
# Passwd &lt;username&gt;
</code></pre><h3 id="第9步-訪問-wetty" tabindex="-1">第9步：訪問 wetty <a class="header-anchor" href="#第9步-訪問-wetty" aria-label="Permalink to “第9步：訪問 wetty”">​</a></h3><pre><code>http://Your_IP-Address:8080
</code></pre><p>輸入你之前為 wetty 創建的證書然後訪問。</p><p>到此結束！</p><hr>`,30)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),n(a,{href:"http://www.unixmen.com/install-wetty-centosrhel-6-x/"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.unixmen.com/install-wetty-centosrhel-6-x/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),n(a,{href:"http://www.unixmen.com/author/debjyoti/"},{default:r(()=>[...e[2]||(e[2]=[t("Debojyoti Das",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),n(a,{href:"https://github.com/strugglingyouth"},{default:r(()=>[...e[3]||(e[3]=[t("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const g=s(h,[["render",y]]);export{f as __pageData,g as default};
